import { z } from 'astro/zod';
import raw from '../data/cv.json';
import { site } from '../data/site';

// Schema of src/data/cv.json (generated by scripts/export-cv.mjs). The build fails if the data does not match.
const date = z.string().regex(/^\d{4}(-\d{2}(-\d{2})?)?$/, 'Expected YYYY, YYYY-MM or YYYY-MM-DD');
const text = z.string().min(1);
const list = z.array(text).optional();

const schema = z.object({
	generated: z.object({ note: text, sourceVersion: z.string(), lastUpdated: date }),
	profile: z.object({
		name: text,
		email: z.email(),
		location: text,
		linkedin: z.url(),
		github: z.url(),
		summary: text,
	}),
	experience: z.array(
		z.object({ id: text, title: text, org: text, location: text.optional(), startDate: date, endDate: date.optional(), summary: text.optional(), bullets: list, tags: list }),
	),
	aiTraining: z.array(
		z.object({ id: text, title: text, program: text.optional(), org: text, location: text.optional(), startDate: date, endDate: date.optional(), status: text.optional(), summary: text.optional(), distinction: text.optional(), credentialUrl: z.url().optional(), image: text.optional(), tags: list }),
	),
	projects: z.array(
		z.object({ id: text, title: text, context: text.optional(), startDate: date, endDate: date.optional(), status: text.optional(), summary: text.optional(), bullets: list, tags: list }),
	),
	education: z.array(
		z.object({ id: text, degree: text, specialization: text.optional(), org: text, location: text.optional(), startDate: date, endDate: date.optional(), distinction: text.optional(), thesis: text.optional(), thesisUrl: z.url().optional(), image: text.optional() }),
	),
	certifications: z.array(
		z.object({ id: text, title: text, issuer: text, date, expiryDate: date.optional(), credentialUrl: z.url().optional(), image: text.optional() }),
	),
	skills: z.object({
		technical: z.array(z.object({ group: text, items: z.array(z.object({ name: text, level: text.optional() })) })),
		soft: z.array(text),
	}),
	languages: z.array(z.object({ language: text, level: text, cefr: text.optional() })),
	publications: z.array(
		z.object({ id: text, type: text, title: text, authors: z.array(text), venue: text.optional(), institution: text.optional(), year: date, volume: text.optional(), pages: text.optional(), articleNumber: text.optional(), doi: text.optional(), url: z.url().optional() }),
	),
	awards: z.array(z.object({ id: text, title: text, org: text, date, endDate: date.optional(), summary: text.optional() })),
	activities: z.array(
		z.object({ id: text, title: text, org: text.optional(), orgs: list, program: text.optional(), event: text.optional(), startDate: date.optional(), endDate: date.optional(), date: date.optional(), bullets: list, tags: list }),
	),
	courses: z.array(z.object({ id: text, title: text, org: text, year: date.optional(), startDate: date.optional(), endDate: date.optional() })),
});

export const cv = schema.parse(raw);
export type Cv = z.infer<typeof schema>;

// ---------- Formatting helpers ----------

const monthYear = new Intl.DateTimeFormat(site.locale, { month: 'short', year: 'numeric', timeZone: 'UTC' });
const longDate = new Intl.DateTimeFormat(site.locale, { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' });

/** "2025" → "2025"; "2025-04" or "2025-04-12" → "abr. 2025". */
export function formatDate(value: string): string {
	const [y, m] = value.split('-').map(Number);
	return m ? monthYear.format(new Date(Date.UTC(y, m - 1, 1))) : String(y);
}

/** Date range for the badge; an open range on current items reads "actualidad". */
export function formatRange(start?: string, end?: string, open = false): string {
	if (!start) return end ? formatDate(end) : '';
	if (!end) return open ? `${formatDate(start)} – actualidad` : formatDate(start);
	if (start === end) return formatDate(start);
	return `${formatDate(start)} – ${formatDate(end)}`;
}

export const formatLongDate = (value: string) => {
	const [y, m, d] = value.split('-').map(Number);
	return longDate.format(new Date(Date.UTC(y, (m ?? 1) - 1, d ?? 1)));
};

/** Spanish list: "a, b y c". */
export const joinList = (items: readonly string[]) => new Intl.ListFormat(site.locale, { type: 'conjunction' }).format(items);

/** Typographic fixes for data text: curly quotes and an en dash for spaced hyphens. */
export const typo = (s: string) => s.replace(/"([^"]*)"/g, '“$1”').replace(/ - /g, ' – ');

/** Authors in citation style: "Amlashi, H.; Karimirad, M. y Barreto, D." keeps surnames and full names readable. */
export const formatAuthors = (authors: readonly string[]) =>
	authors.length > 1 ? `${authors.slice(0, -1).join('; ')} y ${authors.at(-1)}` : (authors[0] ?? '');

/** DOI as stored may be a bare identifier or a full https://doi.org/ URL. */
export const doiOf = (doi: string) => doi.replace(/^https?:\/\/(dx\.)?doi\.org\//i, '');
